1	package com.example.starter.cosmetic.service;
2	
3	import com.example.starter.cosmetic.domain.ChangeType;
4	import com.example.starter.cosmetic.domain.FilingRecord;
5	import com.example.starter.cosmetic.domain.FilingStatus;
6	import com.example.starter.cosmetic.domain.FormulationIngredient;
7	import com.example.starter.cosmetic.domain.ReviewDetail;
8	import com.example.starter.cosmetic.domain.TestReportRecord;
9	import com.example.starter.cosmetic.port.ActiveSlot;
10	import com.example.starter.cosmetic.port.FilingPort;
11	import com.example.starter.cosmetic.port.CatalogPort;
12	import com.example.starter.cosmetic.port.IdempotencyPort;
13	import com.example.starter.cosmetic.port.IdempotencyRow;
14	import com.example.starter.cosmetic.port.ReportPort;
15	import com.example.starter.cosmetic.support.FingerprintSupport;
16	import com.example.starter.cosmetic.support.JsonSupport;
17	import com.example.starter.cosmetic.web.dto.ChangeFilingRequest;
18	import com.example.starter.cosmetic.web.dto.FilingResponse;
19	import com.example.starter.cosmetic.web.dto.FilingResultResponse;
20	import com.example.starter.cosmetic.web.dto.FormulationItemRequest;
21	import com.example.starter.cosmetic.web.dto.SubmitFilingRequest;
22	import com.example.starter.cosmetic.web.dto.TestReportRequest;
23	import com.example.starter.cosmetic.web.dto.ReviewDetailResponse;
24	import org.springframework.dao.DataIntegrityViolationException;
25	import org.springframework.stereotype.Service;
26	import org.springframework.transaction.annotation.Transactional;
27	
28	import java.time.Clock;
29	import java.time.Instant;
30	import java.time.LocalDate;
31	import java.time.ZoneOffset;
32	import java.util.ArrayList;
33	import java.util.LinkedHashMap;
34	import java.util.List;
35	import java.util.Map;
36	import java.util.Optional;
37	
38	/**
39	 * 备案领域服务默认实现。
40	 *
41	 * <p>所有写操作以 requestId 幂等：指纹覆盖 requestId 与全部业务字段，
42	 * 同键同参返回首次结果（idempotentReplay=true），同键异参 409。</p>
43	 */
44	@Service
45	public class FilingServiceImpl implements FilingService {
46	
47	    private static final String OP_SUBMIT = "SUBMIT";
48	    private static final String OP_CHANGE = "CHANGE";
49	    private static final String OP_WITHDRAW = "WITHDRAW";
50	    private static final int PUBLIC_NOTICE_DAYS = 10;
51	    private static final long IDEMPOTENCY_WAIT_NANOS = 10_000_000_000L;
52	    private static final long IDEMPOTENCY_WAIT_STEP_MS = 20L;
53	
54	    private final FilingPort filingPort;
55	    private final CatalogPort catalogPort;
56	    private final ReportPort reportPort;
57	    private final IdempotencyPort idempotencyPort;
58	    private final PublicNoticeEffector publicNoticeEffector;
59	    private final Clock clock;
60	    private final FormReviewEvaluator formReviewEvaluator;
61	
62	    public FilingServiceImpl(FilingPort filingPort,
63	                             CatalogPort catalogPort,
64	                             ReportPort reportPort,
65	                             IdempotencyPort idempotencyPort,
66	                             PublicNoticeEffector publicNoticeEffector,
67	                             Clock clock) {
68	        this.filingPort = filingPort;
69	        this.catalogPort = catalogPort;
70	        this.reportPort = reportPort;
71	        this.idempotencyPort = idempotencyPort;
72	        this.publicNoticeEffector = publicNoticeEffector;
73	        this.clock = clock;
74	        this.formReviewEvaluator = new FormReviewEvaluator(catalogPort);
75	    }
76	
77	    private Instant now() {
78	        return clock.instant();
79	    }
80	
81	    // ============================ 备案提交 ============================
82	
83	    @Override
84	    @Transactional
85	    public FilingResultResponse submit(SubmitFilingRequest request) {
86	        Instant now = now();
87	        Map<String, Object> fingerprintFields = new LinkedHashMap<>();
88	        fingerprintFields.put("requestId", request.requestId());
89	        fingerprintFields.put("productCode", request.productCode());
90	        fingerprintFields.put("productName", request.productName());
91	        fingerprintFields.put("formulation", request.formulation());
92	        fingerprintFields.put("claims", request.claims());
93	        fingerprintFields.put("reports", request.reports() == null ? List.of() : request.reports());
94	        String fingerprint = FingerprintSupport.sha256(fingerprintFields);
95	
96	        Optional<FilingResultResponse> replay =
97	                resolveIdempotency(request.requestId(), OP_SUBMIT, fingerprint);
98	        if (replay.isPresent()) {
99	            return replay.get();
100	        }
101	
102	        List<FormulationIngredient> formulation = request.formulation().stream()
103	                .map(i -> new FormulationIngredient(i.code(), i.name(), i.concentrationPct()))
104	                .toList();
105	        List<String> claims = List.copyOf(request.claims());
106	        List<TestReportRecord> reports = registerReports(request.reports());
107	
108	        int versionNo = filingPort.nextProductVersion(request.productCode());
109	        String filingNo = allocateFilingNo();
110	        LocalDate submitDate = LocalDate.ofInstant(now, ZoneOffset.UTC);
111	
112	        FormReviewEvaluator.Result review = formReviewEvaluator.evaluate(
113	                request.productName(), formulation, claims, reports, submitDate, now, filingNo, versionNo);
114	
115	        List<ReviewDetail> details = new ArrayList<>(review.details());
116	        // 注销后新宣称审查一律拒绝（独立规则，可复算）
117	        boolean postWithdrawalBlocked = filingPort.hasWithdrawnRecord(request.productCode());
118	        if (postWithdrawalBlocked) {
119	            details.add(new ReviewDetail(null, filingNo, versionNo, FormReviewEvaluator.STAGE_FORM,
120	                    "POST_WITHDRAWAL_NEW_CLAIM_REJECTED", false,
121	                    "该产品存在已注销备案，注销后新宣称审查一律拒绝", now));
122	        }
123	        // 同一产品存在未终态（在途/有效）备案时，不得再次新提交
124	        boolean inflightBlocked = hasInFlightFiling(request.productCode());
125	        if (inflightBlocked) {
126	            details.add(new ReviewDetail(null, filingNo, versionNo, FormReviewEvaluator.STAGE_FORM,
127	                    "PRODUCT_ALREADY_IN_FLIGHT", false,
128	                    "同一产品已存在公示/异议审查/生效中的备案，应通过变更接口办理", now));
129	        }
130	
131	        boolean passed = review.passed() && !postWithdrawalBlocked && !inflightBlocked;
132	        List<String> reasons = new ArrayList<>(review.reasons());
133	        if (postWithdrawalBlocked) {
134	            reasons.add("[POST_WITHDRAWAL_NEW_CLAIM_REJECTED] 注销后新宣称审查一律拒绝");
135	        }
136	        if (inflightBlocked) {
137	            reasons.add("[PRODUCT_ALREADY_IN_FLIGHT] 同一产品只允许一个在途/有效备案");
138	        }
139	
140	        FilingStatus status = passed ? FilingStatus.PUBLIC : FilingStatus.FORM_REJECTED;
141	        LocalDate noticeDate = passed ? submitDate : null;
142	        Instant expiresAt = passed ? publicExpiry(noticeDate) : null;
143	
144	        FilingRecord record = new FilingRecord(
145	                null, filingNo, request.productCode(), request.productName(), versionNo, null,
146	                ChangeType.INITIAL, status, formulation, claims, reports, null,
147	                request.requestId(), now, now, noticeDate, expiresAt, null,
148	                null, null, passed ? null : String.join("；", reasons));
149	
150	        filingPort.saveReviews(details);
151	        filingPort.insert(record);
152	
153	        FilingRecord saved = filingPort.findLatestByNo(filingNo).orElseThrow();
154	        FilingResultResponse response = buildResult(saved, details, false, now);
155	        idempotencyPort.complete(request.requestId(), 200, status.name(), filingNo,
156	                JsonSupport.toJson(response), now);
157	        return response;
158	    }
159	
160	    // ============================ 备案变更 ============================
161	
162	    @Override
163	    @Transactional
164	    public FilingResultResponse change(String productCode, ChangeFilingRequest request) {
165	        Instant now = now();
166	        Map<String, Object> fingerprintFields = new LinkedHashMap<>();
167	        fingerprintFields.put("requestId", request.requestId());
168	        fingerprintFields.put("productCode", productCode);
169	        fingerprintFields.put("productName", request.productName());
170	        fingerprintFields.put("formulation", request.formulation());
171	        fingerprintFields.put("claims", request.claims());
172	        fingerprintFields.put("reports", request.reports());
173	        fingerprintFields.put("packagingText", request.packagingText());
174	        String fingerprint = FingerprintSupport.sha256(fingerprintFields);
175	
176	        Optional<FilingResultResponse> replay = resolveIdempotency(request.requestId(), OP_CHANGE, fingerprint);
177	        if (replay.isPresent()) {
178	            return replay.get();
179	        }
180	
181	        ActiveSlot slot = filingPort.findActiveSlot(productCode)
182	                .orElseThrow(() -> new ConflictException("NO_ACTIVE_FILING",
183	                        "产品当前无有效备案，无法变更（可能尚未生效或已注销）: " + productCode));
184	        FilingRecord current = filingPort.findVersion(slot.filingNo(), slot.versionNo())
185	                .orElseThrow(() -> new IllegalStateException("有效槽指向版本不存在"));
186	        if (current.status() != FilingStatus.EFFECTIVE) {
187	            throw new ConflictException("ACTIVE_FILING_NOT_EFFECTIVE",
188	                    "当前有效槽备案状态异常: " + current.status());
189	        }
190	        // 上一实质变更新版本仍在公示/异议审查时，不允许叠加变更，避免多个在途版本竞争同一有效槽
191	        boolean anotherInFlight = filingPort.findByProduct(productCode).stream()
192	                .anyMatch(r -> r.id() != current.id()
193	                        && (r.status() == FilingStatus.PUBLIC
194	                        || r.status() == FilingStatus.OBJECTION_REVIEW));
195	        if (anotherInFlight) {
196	            throw new ConflictException("PREVIOUS_CHANGE_IN_PUBLICITY",
197	                    "该产品已有变更版本处于公示/异议审查中，须待其形成终态后再变更");
198	        }
199	
200	        String newName = request.productName() == null ? current.productName() : request.productName();
201	        List<FormulationIngredient> newFormulation = request.formulation() == null
202	                ? current.formulation()
203	                : request.formulation().stream()
204	                .map(i -> new FormulationIngredient(i.code(), i.name(), i.concentrationPct())).toList();
205	        List<String> newClaims = request.claims() == null ? current.claims() : List.copyOf(request.claims());
206	        List<TestReportRecord> newReports = request.reports() == null
207	                ? current.reports()
208	                : registerReports(request.reports());
209	        String newPackaging = request.packagingText() == null
210	                ? current.packagingText()
211	                : request.packagingText();
212	
213	        boolean formulationChanged = !newFormulation.equals(current.formulation());
214	        boolean claimsChanged = !newClaims.equals(current.claims());
215	        boolean packagingChanged = !nullSafeEquals(newPackaging, current.packagingText());
216	        boolean nameChanged = !newName.equals(current.productName());
217	
218	        if (!formulationChanged && !claimsChanged && !packagingChanged && !nameChanged) {
219	            throw new ConflictException("NO_CHANGE", "变更内容与当前有效备案完全一致，无需变更");
220	        }
221	
222	        int versionNo = filingPort.nextProductVersion(productCode);
223	
224	        if (formulationChanged || claimsChanged) {
225	            return substantiveChange(request.requestId(), current, productCode, newName, newFormulation,
226	                    newClaims, newReports, newPackaging, versionNo, now);
227	        }
228	        return simpleChange(request.requestId(), current, productCode, newName, newFormulation,
229	                newClaims, newReports, newPackaging, versionNo, now);
230	    }
231	
232	    private FilingResultResponse substantiveChange(String requestId,
233	                                                   FilingRecord current,
234	                                                   String productCode,
235	                                                   String newName,
236	                                                   List<FormulationIngredient> newFormulation,
237	                                                   List<String> newClaims,
238	                                                   List<TestReportRecord> newReports,
239	                                                   String newPackaging,
240	                                                   int versionNo,
241	                                                   Instant now) {
242	        String newFilingNo = allocateFilingNo();
243	        LocalDate submitDate = LocalDate.ofInstant(now, ZoneOffset.UTC);
244	        FormReviewEvaluator.Result review = formReviewEvaluator.evaluate(
245	                newName, newFormulation, newClaims, newReports, submitDate, now, newFilingNo, versionNo);
246	
247	        boolean passed = review.passed();
248	        FilingStatus status = passed ? FilingStatus.PUBLIC : FilingStatus.FORM_REJECTED;
249	        LocalDate noticeDate = passed ? submitDate : null;
250	        Instant expiresAt = passed ? publicExpiry(noticeDate) : null;
251	
252	        FilingRecord record = new FilingRecord(
253	                null, newFilingNo, productCode, newName, versionNo, current.filingNo(),
254	                ChangeType.SUBSTANTIVE, status, newFormulation, newClaims, newReports, newPackaging,
255	                requestId, now, now, noticeDate, expiresAt, null, null, null,
256	                passed ? null : String.join("；", review.reasons()));
257	        filingPort.saveReviews(review.details());
258	        filingPort.insert(record);
259	
260	        // 实质变更审查通过进入公示；旧备案在新版本生效前继续有效，待期满同事务切换。
261	        FilingRecord saved = filingPort.findLatestByNo(newFilingNo).orElseThrow();
262	        FilingResultResponse response = buildResult(saved, review.details(), false, now);
263	        idempotencyPort.complete(requestId, 200, status.name(), newFilingNo,
264	                JsonSupport.toJson(response), now);
265	        return response;
266	    }
267	
268	    private FilingResultResponse simpleChange(String requestId,
269	                                              FilingRecord current,
270	                                              String productCode,
271	                                              String newName,
272	                                              List<FormulationIngredient> newFormulation,
273	                                              List<String> newClaims,
274	                                              List<TestReportRecord> newReports,
275	                                              String newPackaging,
276	                                              int versionNo,
277	                                              Instant now) {
278	        // 包装文字类（含产品名称文字）简易变更：引用原备案编号，不重新公示，即时生效。
279	        FilingRecord record = new FilingRecord(
280	                null, current.filingNo(), productCode, newName, versionNo, current.filingNo(),
281	                ChangeType.SIMPLE, FilingStatus.EFFECTIVE, newFormulation, newClaims, newReports,
282	                newPackaging, requestId, now, now, null, null, null, now, null, null);
283	        filingPort.insert(record);
284	
285	        boolean superseded = filingPort.supersedeEffective(current.id(), now);
286	        if (!superseded) {
287	            // 并发下旧有效版本已被另一变更替代：本事务回滚，返回 409
288	            throw new ConflictException("FILING_ALREADY_CHANGED",
289	                    "当前有效版本已被其他变更替代，本次简易变更失败（唯一有效备案）");
290	        }
291	        filingPort.replaceSlot(productCode, current.filingNo(), versionNo, now);
292	
293	        List<ReviewDetail> details = List.of(new ReviewDetail(null, current.filingNo(), versionNo,
294	                FormReviewEvaluator.STAGE_FORM, "SIMPLE_CHANGE_NO_REVIEW", true,
295	                "仅包装文字类变更，走简易变更，引用原备案编号 " + current.filingNo()
296	                        + "，不重新形式审查与公示，即时生效", now));
297	        filingPort.saveReviews(details);
298	
299	        FilingRecord saved = filingPort.findVersion(current.filingNo(), versionNo).orElseThrow();
300	        FilingResultResponse response = buildResult(saved, details, false, now);
301	        idempotencyPort.complete(requestId, 200, FilingStatus.EFFECTIVE.name(), current.filingNo(),
302	                JsonSupport.toJson(response), now);
303	        return response;
304	    }
305	
306	    // ============================ 公示异议 ============================
307	
308	    @Override
309	    @Transactional
310	    public FilingResultResponse acceptObjection(String filingNo, Instant atUtc, String reason) {
311	        Instant objectionAt = atUtc == null ? now() : atUtc;
312	        FilingRecord record = filingPort.findLatestByNo(filingNo)
313	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo));
314	        if (record.status() != FilingStatus.PUBLIC) {
315	            throw new ConflictException("NOT_IN_PUBLICITY",
316	                    "当前状态不受理公示异议: " + record.status()
317	                            + "（公示与异议竞争唯一终态，可能已期满生效）");
318	        }
319	        // 期满时刻之后到达的异议无效；恰期满时刻(==)允许与自动生效并发竞争，由原子更新判定唯一终态
320	        if (record.publicExpiresAtUtc() != null && objectionAt.isAfter(record.publicExpiresAtUtc())) {
321	            throw new ConflictException("PUBLICITY_ALREADY_EXPIRED",
322	                    "异议受理时刻(UTC)=" + objectionAt + " 晚于公示期满时刻(UTC)="
323	                            + record.publicExpiresAtUtc() + "，异议不再受理");
324	        }
325	        boolean accepted = filingPort.acceptObjectionIfPublic(record.id(), objectionAt);
326	        if (!accepted) {
327	            throw new ConflictException("PUBLICITY_ALREADY_EXPIRED",
328	                    "公示已期满生效，异议不再受理（唯一终态）");
329	        }
330	        ReviewDetail detail = new ReviewDetail(null, filingNo, record.versionNo(), "OBJECTION",
331	                "OBJECTION_ACCEPTED", true,
332	                "公示期内受理异议，受理时刻(UTC)=" + objectionAt + "，转入异议审查；原因=" + reason,
333	                objectionAt);
334	        filingPort.saveReviews(List.of(detail));
335	
336	        FilingRecord updated = filingPort.findById(record.id()).orElseThrow();
337	        return buildResult(updated, List.of(detail), false, objectionAt);
338	    }
339	
340	    @Override
341	    @Transactional
342	    public FilingResultResponse resolveObjection(String filingNo, boolean objectionUpheld, String conclusion) {
343	        Instant now = now();
344	        FilingRecord record = filingPort.findLatestByNo(filingNo)
345	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo));
346	        if (record.status() != FilingStatus.OBJECTION_REVIEW) {
347	            throw new ConflictException("NOT_IN_OBJECTION_REVIEW",
348	                    "仅异议审查中的备案可作出异议结论，当前状态: " + record.status());
349	        }
350	        ReviewDetail detail;
351	        FilingRecord updated;
352	        if (objectionUpheld) {
353	            filingPort.markRejectedAfterObjection(record.id(), now, conclusion);
354	            detail = new ReviewDetail(null, filingNo, record.versionNo(), "OBJECTION",
355	                    "OBJECTION_UPHELD", false,
356	                    "异议成立，备案终态驳回：" + conclusion, now);
357	        } else {
358	            filingPort.reopenPublic(record.id());
359	            detail = new ReviewDetail(null, filingNo, record.versionNo(), "OBJECTION",
360	                    "OBJECTION_NOT_UPHELD", true,
361	                    "异议不成立，恢复公示；公示期满仍按原起算日 "
362	                            + record.publicNoticeDateUtc() + "（UTC）计算，期满时刻 "
363	                            + record.publicExpiresAtUtc() + "（UTC）：" + conclusion, now);
364	        }
365	        filingPort.saveReviews(List.of(detail));
366	        updated = filingPort.findById(record.id()).orElseThrow();
367	        return buildResult(updated, List.of(detail), false, now);
368	    }
369	
370	    // ============================ 注销 ============================
371	
372	    @Override
373	    @Transactional
374	    public FilingResultResponse withdraw(String filingNo, String requestId, String reason) {
375	        Instant now = now();
376	        Map<String, Object> fpFields = new LinkedHashMap<>();
377	        fpFields.put("requestId", requestId);
378	        fpFields.put("filingNo", filingNo);
379	        fpFields.put("reason", reason);
380	        String fingerprint = FingerprintSupport.sha256(fpFields);
381	
382	        Optional<FilingResultResponse> replay = resolveIdempotency(requestId, OP_WITHDRAW, fingerprint);
383	        if (replay.isPresent()) {
384	            return replay.get();
385	        }
386	
387	        FilingRecord record = filingPort.findLatestByNo(filingNo)
388	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo));
389	
390	        // 注销为终态：重复注销返回幂等成功
391	        if (record.status() == FilingStatus.WITHDRAWN) {
392	            FilingResultResponse response = buildResult(record,
393	                    filingPort.findReviews(filingNo, record.versionNo()), true, now);
394	            idempotencyPort.complete(requestId, 200, FilingStatus.WITHDRAWN.name(), filingNo,
395	                    JsonSupport.toJson(response), now);
396	            return response;
397	        }
398	        if (record.status() != FilingStatus.EFFECTIVE) {
399	            throw new ConflictException("NOT_EFFECTIVE",
400	                    "仅生效备案可注销，当前状态: " + record.status());
401	        }
402	
403	        filingPort.markWithdrawn(record.id(), now, reason);
404	        filingPort.releaseSlot(record.productCode());
405	        ReviewDetail detail = new ReviewDetail(null, filingNo, record.versionNo(), "FORM",
406	                "WITHDRAWN_TERMINAL", true,
407	                "备案注销终态，注销时刻(UTC)=" + now + "，原因=" + reason
408	                        + "；注销后该产品新宣称审查一律拒绝", now);
409	        filingPort.saveReviews(List.of(detail));
410	
411	        FilingRecord updated = filingPort.findById(record.id()).orElseThrow();
412	        FilingResultResponse response = buildResult(updated, List.of(detail), false, now);
413	        idempotencyPort.complete(requestId, 200, FilingStatus.WITHDRAWN.name(), filingNo,
414	                JsonSupport.toJson(response), now);
415	        return response;
416	    }
417	
418	    // ============================ 查询 ============================
419	
420	    @Override
421	    @Transactional(readOnly = true)
422	    public FilingResponse getFiling(String filingNo) {
423	        return FilingResponse.from(filingPort.findLatestByNo(filingNo)
424	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo)));
425	    }
426	
427	    @Override
428	    @Transactional(readOnly = true)
429	    public List<FilingResponse> getProductHistory(String productCode) {
430	        List<FilingRecord> records = filingPort.findByProduct(productCode);
431	        if (records.isEmpty()) {
432	            throw new NotFoundException("产品无备案历史: " + productCode);
433	        }
434	        return records.stream().map(FilingResponse::from).toList();
435	    }
436	
437	    @Override
438	    @Transactional(readOnly = true)
439	    public List<ReviewDetailResponse> getReviews(String filingNo, Integer versionNo) {
440	        filingPort.findLatestByNo(filingNo)
441	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo));
442	        return filingPort.findReviews(filingNo, versionNo).stream()
443	                .map(ReviewDetailResponse::from).toList();
444	    }
445	
446	    @Override
447	    public int expireDuePublicNotices(Instant now) {
448	        Instant at = now == null ? now() : now;
449	        int effected = 0;
450	        for (FilingRecord record : filingPort.findDuePublicFilings(at)) {
451	            if (publicNoticeEffector.effectuate(record, at)) {
452	                effected++;
453	            }
454	        }
455	        return effected;
456	    }
457	
458	    // ============================ 辅助方法 ============================
459	
460	    private Optional<FilingResultResponse> resolveIdempotency(String requestId,
461	                                                              String operation,
462	                                                              String fingerprint) {
463	        Optional<IdempotencyRow> existing = idempotencyPort.find(requestId);
464	        if (existing.isEmpty()) {
465	            try {
466	                idempotencyPort.claim(requestId, operation, fingerprint);
467	                return Optional.empty();
468	            } catch (DataIntegrityViolationException e) {
469	                // 并发同键：另一个事务刚刚插入主张行，落入下方重读判定
470	                existing = idempotencyPort.find(requestId);
471	                if (existing.isEmpty()) {
472	                    throw e;
473	                }
474	            }
475	        }
476	        IdempotencyRow row = existing.orElseThrow();
477	        if (!row.operation().equals(operation)) {
478	            throw new ConflictException("IDEMPOTENCY_KEY_CROSSED_OPERATION",
479	                    "requestId 已用于其它操作类型: " + row.operation());
480	        }
481	        if (!row.fingerprint().equals(fingerprint)) {
482	            throw new ConflictException("IDEMPOTENCY_PARAM_MISMATCH",
483	                    "同一 requestId 对应不同业务参数，拒绝处理（409）");
484	        }
485	        // 同键同参但首个事务尚未回填（并发重放）：等待首个事务完成后返回首次结果
486	        if (row.httpStatus() == 0 || row.responseJson() == null || row.responseJson().isEmpty()) {
487	            row = awaitFirstCompletion(requestId);
488	        }
489	        FilingResultResponse first = JsonSupport.fromJson(row.responseJson(), FilingResultResponse.class);
490	        return Optional.of(new FilingResultResponse(first.httpStatus(), first.filing(),
491	                true, first.reviewDetails(), first.atUtc()));
492	    }
493	
494	    /**
495	     * 并发重放时等待首个事务回填响应；带超时，避免首个事务异常时无限等待。
496	     */
497	    private IdempotencyRow awaitFirstCompletion(String requestId) {
498	        long deadline = System.nanoTime() + IDEMPOTENCY_WAIT_NANOS;
499	        IdempotencyRow row;
500	        do {
501	            try {
502	                Thread.sleep(IDEMPOTENCY_WAIT_STEP_MS);
503	            } catch (InterruptedException e) {
504	                Thread.currentThread().interrupt();
505	                throw new ConflictException("IDEMPOTENCY_WAIT_INTERRUPTED",
506	                        "等待首次处理结果时被中断: " + requestId);
507	            }
508	            row = idempotencyPort.find(requestId).orElseThrow(() ->
509	                    new ConflictException("IDEMPOTENCY_RECORD_VANISHED", "幂等记录消失: " + requestId));
510	        } while ((row.httpStatus() == 0 || row.responseJson() == null || row.responseJson().isEmpty())
511	                && System.nanoTime() < deadline);
512	
513	        if (row.httpStatus() == 0 || row.responseJson() == null || row.responseJson().isEmpty()) {
514	            throw new ConflictException("IDEMPOTENCY_FIRST_RESULT_TIMEOUT",
515	                    "等待首次处理结果超时: " + requestId);
516	        }
517	        return row;
518	    }
519	
520	    private List<TestReportRecord> registerReports(List<TestReportRequest> requests) {
521	        List<TestReportRecord> records = new ArrayList<>();
522	        for (TestReportRequest r : requests == null ? List.<TestReportRequest>of() : requests) {
523	            TestReportRecord rec = new TestReportRecord(r.reportNo(), r.efficacyCode(), r.issuedDate(),
524	                    Boolean.TRUE.equals(r.conclusionSupported()), r.conclusionText());
525	            reportPort.upsert(rec);
526	            records.add(rec);
527	        }
528	        return List.copyOf(records);
529	    }
530	
531	    private boolean hasInFlightFiling(String productCode) {
532	        return filingPort.findByProduct(productCode).stream()
533	                .anyMatch(r -> r.status() == FilingStatus.PUBLIC
534	                        || r.status() == FilingStatus.OBJECTION_REVIEW
535	                        || r.status() == FilingStatus.EFFECTIVE
536	                        || r.status() == FilingStatus.SUBMITTED);
537	    }
538	
539	    private String allocateFilingNo() {
540	        long seq = filingPort.nextFilingSequence();
541	        return String.format("SYN-F-%06d", seq);
542	    }
543	
544	    /**
545	     * 公示期满口径：起算日 D（UTC）起 10 个自然日，恰第 10 日 24:00 期满，
546	     * 即 D+10 日 00:00:00 UTC（到期判定使用 &lt;=，恰期满当时即可生效）。
547	     */
548	    private Instant publicExpiry(LocalDate noticeDateUtc) {
549	        return noticeDateUtc.plusDays(PUBLIC_NOTICE_DAYS)
550	                .atStartOfDay().toInstant(ZoneOffset.UTC);
551	    }
552	
553	    private FilingResultResponse buildResult(FilingRecord record,
554	                                             List<ReviewDetail> details,
555	                                             boolean replay,
556	                                             Instant atUtc) {
557	        List<ReviewDetailResponse> detailResponses = details.stream()
558	                .map(ReviewDetailResponse::from).toList();
559	        return new FilingResultResponse(200, FilingResponse.from(record), replay,
560	                detailResponses, atUtc);
561	    }
562	
563	    private static boolean nullSafeEquals(String a, String b) {
564	        return a == null ? b == null : a.equals(b);
565	    }
566	}
