20	/**
21	 * 形式审查规则计算器（无外部状态，可单测复算）。
22	 *
23	 * <p>规则口径：</p>
24	 * <ol>
25	 *   <li>DOC_COMPLETE：备案资料齐全（产品名、配方、宣称均非空）。</li>
26	 *   <li>CLAIM_CATALOG：宣称功效须在合成目录内；不支持的功效宣称拒绝。</li>
27	 *   <li>SPECIAL_REPORT_PRESENT：特殊功效（防晒、美白、祛斑等）须有对应功效评价试验报告。</li>
28	 *   <li>REPORT_VALIDITY：报告须为备案提交日前 3 年内出具（UTC 日界），恰满 3 年当日有效；
29	 *       且出具日不得晚于提交日。</li>
30	 *   <li>CLAIM_REPORT_CONSISTENCY：宣称与报告结论须一致（报告结论支持对应功效）。</li>
31	 *   <li>RESTRICTED_CONCENTRATION：配方含限用成分的浓度不得超过限值，恰等限值合法。</li>
32	 * </ol>
33	 */
34	public class FormReviewEvaluator {
35	
36	    /** 规则阶段标识。 */
37	    public static final String STAGE_FORM = "FORM";
38	
39	    /** 报告有效期年数。 */
40	    public static final int REPORT_VALID_YEARS = 3;
41	
42	    private final CatalogPort catalogPort;
43	
44	    public FormReviewEvaluator(CatalogPort catalogPort) {
45	        this.catalogPort = catalogPort;
46	    }
47	
48	    /**
49	     * 形式审查结果。
50	     *
51	     * @param passed  全部规则是否通过
52	     * @param details 逐条审查明细（含通过/不通过，可复算）
53	     * @param reasons 不通过原因汇总
54	     */
55	    public record Result(boolean passed, List<ReviewDetail> details, List<String> reasons) {
56	    }
57	
58	    /**
59	     * 执行形式审查。
60	     *
61	     * @param productName 产品名称
62	     * @param formulation 配方快照
63	     * @param claims      功效宣称编码
64	     * @param reports     随附试验报告快照
65	     * @param submitDate  备案提交日（UTC 日界）
66	     * @param nowUtc      明细记录时刻(UTC)
67	     * @param filingNo    备案编号（驳回件亦分配编号）
68	     * @param versionNo   版本号
69	     */
70	    public Result evaluate(String productName,
71	                           List<FormulationIngredient> formulation,
72	                           List<String> claims,
73	                           List<TestReportRecord> reports,
74	                           LocalDate submitDate,
75	                           java.time.Instant nowUtc,
76	                           String filingNo,
77	                           int versionNo) {
78	        List<ReviewDetail> details = new ArrayList<>();
79	        List<String> reasons = new ArrayList<>();
80	
81	        evaluateDocuments(productName, formulation, claims, details, reasons, nowUtc, filingNo, versionNo);
82	        Map<String, EfficacyCatalog> claimCatalogs =
83	                evaluateCatalog(claims, details, reasons, nowUtc, filingNo, versionNo);
84	        Set<String> claimedSpecials =
85	                evaluateSpecialReports(claims, reports, claimCatalogs, details, reasons, nowUtc, filingNo, versionNo);
86	        Map<String, TestReportRecord> specialReports =
87	                evaluateReportValidityAndConsistency(claims, reports, claimCatalogs, claimedSpecials, submitDate,
88	                        details, reasons, nowUtc, filingNo, versionNo);
89	        evaluateConcentration(formulation, details, reasons, nowUtc, filingNo, versionNo);
90	
91	        return new Result(reasons.isEmpty(), List.copyOf(details), List.copyOf(reasons));
92	    }
93	
94	    private void evaluateDocuments(String productName,
95	                                   List<FormulationIngredient> formulation,
96	                                   List<String> claims,
97	                                   List<ReviewDetail> details,
98	                                   List<String> reasons,
99	                                   java.time.Instant now,
100	                                   String filingNo,
101	                                   int versionNo) {
102	        boolean nameOk = productName != null && !productName.isBlank();
103	        boolean formulationOk = formulation != null && !formulation.isEmpty();
104	        boolean claimsOk = claims != null && !claims.isEmpty();
105	        boolean passed = nameOk && formulationOk && claimsOk;
106	        String detail = String.format(
107	                "资料齐全性：产品名称=%s，配方条目数=%d，功效宣称数=%d",
108	                nameOk ? "齐全" : "缺失",
109	                formulation == null ? 0 : formulation.size(),
110	                claims == null ? 0 : claims.size());
111	        add(details, reasons, now, filingNo, versionNo, "DOC_COMPLETE", passed, detail);
112	    }
113	
114	    private Map<String, EfficacyCatalog> evaluateCatalog(List<String> claims,
115	                                                         List<ReviewDetail> details,
116	                                                         List<String> reasons,
117	                                                         java.time.Instant now,
118	                                                         String filingNo,
119	                                                         int versionNo) {
120	        Map<String, EfficacyCatalog> resolved = new HashMap<>();
121	        boolean passed = true;
122	        List<String> problems = new ArrayList<>();
123	        for (String code : claims == null ? List.<String>of() : claims) {
124	            Optional<EfficacyCatalog> cat = catalogPort.findEfficacy(code);
125	            if (cat.isEmpty()) {
126	                passed = false;
127	                problems.add("功效编码不在合成目录: " + code);
128	            } else {
129	                EfficacyCatalog c = cat.get();
130	                resolved.put(code, c);
131	                if (!c.supported()) {
132	                    passed = false;
133	                    problems.add("不支持的功效宣称，拒绝: " + code + "(" + c.name() + ")");
134	                }
135	            }
136	        }
137	        add(details, reasons, now, filingNo, versionNo, "CLAIM_CATALOG", passed,
138	                "功效宣称目录校验：" + (passed ? "全部宣称在支持目录内" : String.join("；", problems)));
139	        return resolved;
140	    }
141	
142	    private Set<String> evaluateSpecialReports(List<String> claims,
143	                                               List<TestReportRecord> reports,
144	                                               Map<String, EfficacyCatalog> claimCatalogs,
145	                                               List<ReviewDetail> details,
146	                                               List<String> reasons,
147	                                               java.time.Instant now,
148	                                               String filingNo,
149	                                               int versionNo) {
150	        Set<String> specials = new HashSet<>();
151	        for (String code : claims == null ? List.<String>of() : claims) {
152	            EfficacyCatalog cat = claimCatalogs.get(code);
153	            if (cat != null && cat.special()) {
154	                specials.add(code);
155	            }
156	        }
157	        Map<String, List<TestReportRecord>> byEfficacy = groupByEfficacy(reports);
158	        boolean passed = true;
159	        List<String> problems = new ArrayList<>();
160	        for (String code : specials) {
161	            if (byEfficacy.getOrDefault(code, List.of()).isEmpty()) {
162	                passed = false;
163	                problems.add("特殊功效缺少对应功效评价试验报告: " + code);
164	            }
165	        }
166	        add(details, reasons, now, filingNo, versionNo, "SPECIAL_REPORT_PRESENT", passed,
167	                "特殊功效报告齐备性：特殊功效=" + specials + "，"
168	                        + (passed ? "均有对应报告" : String.join("；", problems)));
169	        return specials;
170	    }
171	
172	    private Map<String, TestReportRecord> evaluateReportValidityAndConsistency(
173	            List<String> claims,
174	            List<TestReportRecord> reports,
175	            Map<String, EfficacyCatalog> claimCatalogs,
176	            Set<String> claimedSpecials,
177	            LocalDate submitDate,
178	            List<ReviewDetail> details,
179	            List<String> reasons,
180	            java.time.Instant now,
181	            String filingNo,
182	            int versionNo) {
183	        LocalDate earliest = submitDate.minusYears(REPORT_VALID_YEARS);
184	        boolean validityPassed = true;
185	        boolean consistencyPassed = true;
186	        List<String> validityProblems = new ArrayList<>();
187	        List<String> consistencyProblems = new ArrayList<>();
188	        Map<String, TestReportRecord> specialReportChosen = new HashMap<>();
189	
190	        // 仅校验对应当前被宣称特殊功效的报告；其余报告不参与本次宣称判定。
191	        for (TestReportRecord r : reports == null ? List.<TestReportRecord>of() : reports) {
192	            if (!claimedSpecials.contains(r.efficacyCode())) {
193	                continue;
194	            }
195	            // 有效期：earliest <= issuedDate <= submitDate；恰满 3 年当日（issuedDate == earliest）有效
196	            boolean dateOk = !r.issuedDate().isBefore(earliest) && !r.issuedDate().isAfter(submitDate);
197	            long ageYears = ChronoUnit.YEARS.between(r.issuedDate(), submitDate);
198	            String validityDetail = String.format(
199	                    "报告 %s（功效 %s）出具日 %s，提交日 %s，3年口径下界 %s（含当日），年限=%d → %s",
200	                    r.reportNo(), r.efficacyCode(), r.issuedDate(), submitDate, earliest, ageYears,
201	                    dateOk ? "在有效期内" : "超出3年有效期或出具日晚于提交日");
202	            if (!dateOk) {
203	                validityPassed = false;
204	                validityProblems.add(validityDetail);
205	            }
206	            // 一致性：报告结论必须支持其对应宣称
207	            if (!r.conclusionSupported()) {
208	                consistencyPassed = false;
209	                consistencyProblems.add(String.format(
210	                        "报告 %s（功效 %s）结论为不支持，与宣称不一致", r.reportNo(), r.efficacyCode()));
211	            } else {
212	                // 同一功效多份报告时，记录其中一份支持的有效报告
213	                specialReportChosen.putIfAbsent(r.efficacyCode(), r);
214	            }
215	        }
216	
217	        add(details, reasons, now, filingNo, versionNo, "REPORT_VALIDITY", validityPassed,
218	                "报告3年有效期（UTC 日界，恰满3年当日有效）："
219	                        + (validityPassed
220	                        ? (claimedSpecials.isEmpty() ? "无特殊功效，免报告" : "全部对应报告在有效期内")
221	                        : String.join("；", validityProblems)));
222	        add(details, reasons, now, filingNo, versionNo, "CLAIM_REPORT_CONSISTENCY", consistencyPassed,
223	                "宣称与报告结论一致性："
224	                        + (consistencyPassed
225	                        ? (claimedSpecials.isEmpty() ? "无特殊功效宣称" : "宣称均与报告结论一致")
226	                        : String.join("；", consistencyProblems)));
227	        return specialReportChosen;
228	    }
229	
230	    private void evaluateConcentration(List<FormulationIngredient> formulation,
231	                                       List<ReviewDetail> details,
232	                                       List<String> reasons,
233	                                       java.time.Instant now,
234	                                       String filingNo,
235	                                       int versionNo) {
236	        boolean passed = true;
237	        List<String> lines = new ArrayList<>();
238	        for (FormulationIngredient ing : formulation == null ? List.<FormulationIngredient>of() : formulation) {
239	            Optional<RestrictedIngredient> limit = catalogPort.findRestricted(ing.code());
240	            if (limit.isEmpty()) {
241	                continue;
242	            }
243	            int cmp = ing.concentrationPct().compareTo(limit.get().maxConcentrationPct());
244	            boolean ok = cmp <= 0;
245	            lines.add(String.format("限用成分 %s 实测 %s%%，限值 %s%%，恰等合法：%s",
246	                    ing.code(), ing.concentrationPct().stripTrailingZeros().toPlainString(),
247	                    limit.get().maxConcentrationPct().stripTrailingZeros().toPlainString(),
248	                    ok ? "通过" : "超限"));
249	            if (!ok) {
250	                passed = false;
251	            }
252	        }
253	        add(details, reasons, now, filingNo, versionNo, "RESTRICTED_CONCENTRATION", passed,
254	                "限用成分浓度校验（恰等限值合法）：" + (lines.isEmpty() ? "配方无限用成分" : String.join("；", lines)));
255	    }
256	
257	    private Map<String, List<TestReportRecord>> groupByEfficacy(List<TestReportRecord> reports) {
258	        Map<String, List<TestReportRecord>> map = new HashMap<>();
259	        for (TestReportRecord r : reports == null ? List.<TestReportRecord>of() : reports) {
260	            map.computeIfAbsent(r.efficacyCode(), k -> new ArrayList<>()).add(r);
261	        }
262	        return map;
263	    }
264	
265	    private void add(List<ReviewDetail> details,
266	                     List<String> reasons,
267	                     java.time.Instant now,
268	                     String filingNo,
269	                     int versionNo,
270	                     String ruleCode,
271	                     boolean passed,
272	                     String detail) {
273	        details.add(new ReviewDetail(null, filingNo, versionNo, STAGE_FORM, ruleCode, passed, detail, now));
274	        if (!passed) {
275	            reasons.add("[" + ruleCode + "] " + detail);
276	        }
277	    }
278	}
