package com.example.starter.cosmetic.domain;

/**
 * 备案变更类型。
 */
public enum ChangeType {

    /** 首次备案。 */
    INITIAL,
    /** 实质变更：涉及配方或功效宣称，重新走形式审查与公示并生成新备案编号。 */
    SUBSTANTIVE,
    /** 简易变更：仅包装文字类调整，不重新公示，生效记录引用原备案编号。 */
    SIMPLE
}

package com.example.starter.cosmetic.domain;

/**
 * 化妆品备案生命周期状态。
 *
 * <p>流转：备案提交(SUBMITTED)→形式审查(通过则进入 PUBLIC，不通过 FORM_REJECTED)
 * →公示(PUBLIC)→生效(EFFECTIVE)；公示期内收到异议转 OBJECTION_REVIEW；
 * 生效后可变更(旧版本 SUPERSEDED)或注销(WITHDRAWN，终态)；
 * 异议成立则 REJECTED_AFTER_OBJECTION(终态)。</p>
 */
public enum FilingStatus {

    /** 已提交，形式审查尚未通过（中间态，提交时同步完成形式审查，实际不会持久停留）。 */
    SUBMITTED(false),
    /** 形式审查驳回（终态）：资料/功效/报告/浓度等规则不满足。 */
    FORM_REJECTED(true),
    /** 公示中：公示期为起算日起 10 个自然日，第 10 日 24:00(UTC) 期满。 */
    PUBLIC(false),
    /** 异议审查中：公示期内收到异议后的唯一分支状态。 */
    OBJECTION_REVIEW(false),
    /** 生效：该产品当前唯一有效的备案。 */
    EFFECTIVE(false),
    /** 已被新版本替代（实质变更新版本生效或简易变更生效时，旧版本同事务转入此态）。 */
    SUPERSEDED(true),
    /** 已注销（终态）：重复注销幂等成功，注销后新宣称审查一律拒绝。 */
    WITHDRAWN(true),
    /** 异议经审查成立，备案驳回（终态）。 */
    REJECTED_AFTER_OBJECTION(true);

    private final boolean terminal;

    FilingStatus(boolean terminal) {
        this.terminal = terminal;
    }

    /** 是否终态：终态备案不再发生状态迁移。 */
    public boolean isTerminal() {
        return terminal;
    }
}

package com.example.starter.cosmetic.domain;

import java.time.LocalDate;

/**
 * 功效评价试验报告（合成数据）。
 *
 * @param reportNo           报告编号
 * @param efficacyCode       报告对应的功效编码
 * @param issuedDate         报告出具日（UTC 日界）；备案提交日前 3 年内有效，恰满 3 年当日有效
 * @param conclusionSupported 报告结论是否支持该功效宣称（宣称与报告结论须一致）
 * @param conclusionText     报告结论文本
 */
public record TestReportRecord(String reportNo,
                               String efficacyCode,
                               LocalDate issuedDate,
                               boolean conclusionSupported,
                               String conclusionText) {
}

package com.example.starter.cosmetic.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDate;

/**
 * 功效评价试验报告请求条目（合成报告由调用方登记后随备案提交引用）。
 *
 * @param reportNo            报告编号
 * @param efficacyCode        报告对应功效编码
 * @param issuedDate          报告出具日（UTC 日界日期，例如 2023-06-30）
 * @param conclusionSupported 报告结论是否支持该功效
 * @param conclusionText      报告结论文本
 */
public record TestReportRequest(
        @NotBlank String reportNo,
        @NotBlank String efficacyCode,
        @NotNull LocalDate issuedDate,
        @NotNull Boolean conclusionSupported,
        String conclusionText) {
}

package com.example.starter.cosmetic.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 备案处理结果响应（提交/变更/异议/注销）。
 *
 * @param httpStatus       等价 HTTP 状态码（200/409 等），便于幂等快照复算
 * @param filing           备案详情
 * @param idempotentReplay 是否为同键同参重放（返回首次结果）
 * @param reviewDetails    本次形式/异议审查明细
 * @param atUtc            处理时刻(UTC)
 */
public record FilingResultResponse(
        int httpStatus,
        FilingResponse filing,
        boolean idempotentReplay,
        List<ReviewDetailResponse> reviewDetails,
        Instant atUtc) {
}

