9	import org.junit.jupiter.api.Test;
10	import org.springframework.beans.factory.annotation.Autowired;
11	
12	import java.time.Instant;
13	import java.util.concurrent.CountDownLatch;
14	import java.util.concurrent.ExecutorService;
15	import java.util.concurrent.Executors;
16	import java.util.concurrent.Future;
17	import java.util.concurrent.TimeUnit;
18	import java.util.concurrent.atomic.AtomicInteger;
19	import java.util.concurrent.atomic.AtomicReference;
20	
21	import static org.assertj.core.api.Assertions.assertThat;
22	
23	/**
24	 * H2 真实并发测试：
25	 * <ul>
26	 *   <li>公示期满自动生效 vs 期内异议受理并发竞争，必须形成唯一终态；</li>
27	 *   <li>同一 requestId 并发提交，仅落一条备案且两个调用都拿到首次结果。</li>
28	 * </ul>
29	 */
30	class FilingConcurrencyIntegrationTest extends AbstractCosmeticIntegrationTest {
31	
32	    @Autowired
33	    private FilingService filingService;
34	
35	    @Autowired
36	    private PublicNoticeEffector publicNoticeEffector;
37	
38	    @Autowired
39	    private FilingPort filingPort;
40	
41	    private static final Instant EXPIRES_EXPECTED = Instant.parse("2026-07-10T00:00:00Z");
42	
43	    /**
44	     * 恰第 10 日 24:00(UTC) 同时发起“期满生效”和“异议受理”，
45	     * 多轮执行确认：不得既生效又受理异议，终态唯一。
46	     */
47	    @Test
48	    void expiryAndObjectionRaceProducesExactlyOneTerminalState() throws Exception {
49	        int rounds = 20;
50	        for (int r = 0; r < rounds; r++) {
51	            final int round = r;
52	            final String product = "P-RACE-" + round;
53	            FilingResultResponse submitted =
54	                    filingService.submit(FilingFixtures.ordinarySubmit("REQ-RACE-" + round, product));
55	            long recordId = filingPort.findLatestByNo(submitted.filing().filingNo()).orElseThrow().id();
56	
57	            CountDownLatch start = new CountDownLatch(1);
58	            AtomicInteger effectiveWins = new AtomicInteger();
59	            AtomicInteger objectionWins = new AtomicInteger();
60	            AtomicReference<Throwable> error = new AtomicReference<>();
61	
62	            Runnable expiryTask = () -> {
63	                try {
64	                    start.await();
65	                    FilingRecord record = filingPort.findById(recordId).orElseThrow();
66	                    if (publicNoticeEffector.effectuate(record, EXPIRES_EXPECTED)) {
67	                        effectiveWins.incrementAndGet();
68	                    }
69	                } catch (Throwable t) {
70	                    error.compareAndSet(null, t);
71	                }
72	            };
73	            Runnable objectionTask = () -> {
74	                try {
75	                    start.await();
76	                    filingService.acceptObjection(submitted.filing().filingNo(),
77	                            EXPIRES_EXPECTED, "恰期满当时异议-轮次" + round);
78	                    objectionWins.incrementAndGet();
79	                } catch (ConflictException e) {
80	                    // 期满分支已获胜：异议必然被拒，不计入异常
81	                } catch (Throwable t) {
82	                    error.compareAndSet(null, t);
83	                }
84	            };
85	
86	            Thread expiryThread = new Thread(expiryTask, "expiry-" + round);
87	            Thread objectionThread = new Thread(objectionTask, "objection-" + round);
88	            expiryThread.start();
89	            objectionThread.start();
90	            start.countDown();
91	            expiryThread.join(10_000);
92	            objectionThread.join(10_000);
93	
94	            assertThat(error.get()).isNull();
95	            assertThat(effectiveWins.get() + objectionWins.get())
96	                    .as("第 %d 轮：两个分支必须恰好一个获胜", round)
97	                    .isEqualTo(1);
98	
99	            FilingStatus finalStatus = filingPort.findById(recordId).orElseThrow().status();
100	            if (effectiveWins.get() == 1) {
101	                assertThat(finalStatus).isEqualTo(FilingStatus.EFFECTIVE);
102	                assertThat(filingPort.findActiveSlot(product)).isPresent();
103	            } else {
104	                assertThat(finalStatus).isEqualTo(FilingStatus.OBJECTION_REVIEW);
105	                assertThat(filingPort.findActiveSlot(product)).isEmpty();
106	            }
107	        }
108	    }
109	
110	    /**
111	     * 同一 requestId 同参数并发提交：数据库主键冲突 + 等待回填保证只有一条备案，
112	     * 两个调用方都返回同一首次结果。
113	     */
114	    @Test
115	    void concurrentSameRequestSubmissionsAreIdempotent() throws Exception {
116	        ExecutorService pool = Executors.newFixedThreadPool(2);
117	        try {
118	            for (int round = 0; round < 8; round++) {
119	                String requestId = "REQ-CONC-" + round;
120	                String product = "P-CONC-" + round;
121	                CountDownLatch start = new CountDownLatch(1);
122	                CountDownLatch done = new CountDownLatch(2);
123	                java.util.List<FilingResultResponse> responses =
124	                        java.util.Collections.synchronizedList(new java.util.ArrayList<>());
125	                AtomicReference<Throwable> error = new AtomicReference<>();
126	
127	                Runnable task = () -> {
128	                    try {
129	                        start.await();
130	                        responses.add(
131	                                filingService.submit(FilingFixtures.ordinarySubmit(requestId, product)));
132	                    } catch (Throwable t) {
133	                        error.compareAndSet(null, t);
134	                    } finally {
135	                        done.countDown();
136	                    }
137	                };
138	
139	                Future<?> f1 = pool.submit(task);
140	                Future<?> f2 = pool.submit(task);
141	                start.countDown();
142	                boolean finished = done.await(30, TimeUnit.SECONDS);
143	                f1.get(1, TimeUnit.SECONDS);
144	                f2.get(1, TimeUnit.SECONDS);
145	
146	                assertThat(finished).as("第 %d 轮并发提交应在超时前完成", round).isTrue();
147	                assertThat(error.get()).isNull();
148	                assertThat(responses).hasSize(2);
149	
150	                // 恰好一个是首次处理，另一个是重放
151	                long replays = responses.stream().filter(FilingResultResponse::idempotentReplay).count();
152	                long initials = responses.stream().filter(r -> !r.idempotentReplay()).count();
153	                assertThat(replays).isEqualTo(1);
154	                assertThat(initials).isEqualTo(1);
155	                assertThat(responses.get(0).filing().filingNo())
156	                        .isEqualTo(responses.get(1).filing().filingNo());
157	                // 只落一条备案、只占一份幂等记录
158	                assertThat(filingPort.findByProduct(product)).hasSize(1);
159	                Integer idemCount = jdbc.queryForObject(
160	                        "SELECT COUNT(1) FROM idempotency_record WHERE request_id = ?",
161	                        Integer.class, requestId);
162	                assertThat(idemCount).isEqualTo(1);
163	            }
164	        } finally {
165	            pool.shutdownNow();
166	        }
167	    }
168	
169	    /**
170	     * 并发简易变更：同一有效备案同时发起两次不同 requestId 的包装变更，
171	     * 最终只有一个新版本生效，旧版本恰好被替代一次（唯一有效备案 + 原子切换）。
172	     */
173	    @Test
174	    void concurrentSimpleChangesLeaveSingleEffectiveVersion() throws Exception {
175	        filingService.submit(FilingFixtures.ordinarySubmit("REQ-S-1", "P-SC-RACE"));
176	        clock.setInstant(EXPIRES_EXPECTED);
177	        filingService.expireDuePublicNotices(null);
178	
179	        CountDownLatch start = new CountDownLatch(1);
180	        AtomicInteger success = new AtomicInteger();
181	        AtomicInteger conflicts = new AtomicInteger();
182	        AtomicReference<Throwable> error = new AtomicReference<>();
183	
184	        Runnable changeA = () -> runChange("REQ-S-2", "包装版本A", start, success, conflicts, error);
185	        Runnable changeB = () -> runChange("REQ-S-3", "包装版本B", start, success, conflicts, error);
186	
187	        Thread t1 = new Thread(changeA);
188	        Thread t2 = new Thread(changeB);
189	        t1.start();
190	        t2.start();
191	        start.countDown();
192	        t1.join(10_000);
193	        t2.join(10_000);
194	
195	        assertThat(error.get()).isNull();
196	        // 恰好一个变更成功；另一个因旧版本已被替代（条件 UPDATE 0 行）回滚
197	        assertThat(success.get() + conflicts.get()).isEqualTo(2);
198	        assertThat(success.get()).isEqualTo(1);
199	        var slot = filingPort.findActiveSlot("P-SC-RACE").orElseThrow();
200	        assertThat(slot.versionNo()).isEqualTo(2);
201	        assertThat(filingPort.findVersion("SYN-F-000001", 1).orElseThrow().status())
202	                .isEqualTo(FilingStatus.SUPERSEDED);
203	    }
204	
205	    private void runChange(String requestId, String packaging, CountDownLatch start,
206	                           AtomicInteger success, AtomicInteger conflicts,
207	                           AtomicReference<Throwable> error) {
208	        try {
209	            start.await();
210	            filingService.change("P-SC-RACE", FilingFixtures.packagingChange(requestId, packaging));
211	            success.incrementAndGet();
212	        } catch (ConflictException | org.springframework.dao.DataIntegrityViolationException e) {
213	            // 业务409 或版本唯一索引竞争（HTTP 层同样映射为409）：输家事务回滚
214	            conflicts.incrementAndGet();
215	        } catch (Throwable t) {
216	            error.compareAndSet(null, t);
217	        }
218	    }
219	}
