    if (r.childDossiers() == null) {
        return null;
    }
    java.util.Map<String, String> labels = new java.util.LinkedHashMap<>();
    r.childDossiers().forEach(d -> labels.put(d.bandCode(), d.labelText()));
    return JsonSupport.toJson(labels);
}

