        @NotNull @Min(0) @Max(144) Integer coverageLowerMonths,
        @NotNull @Min(0) @Max(144) Integer coverageUpperMonths,
        @NotNull Boolean conclusionSupported,
        String conclusionText,
        @NotBlank String labelText) {
}

